      lblTotalStaff: 'Jami', lblActiveStaff: 'Faol (30 kun ichida)', lblBlockedStaff: 'Bloklangan',
      colDate:'Sana', colTime:'Vaqt', colProduct:'Tovar', colCategory:'Kategoriya',
